/**
 * SAML Relying Parties LIST + CREATE router (samlgw2)
 *
 * GET: Lists all SAML RPs for the tenant by querying samlgw2 customer data
 *      and merging with DynamoDB SP info (released, logoUrl, serviceUrl).
 * POST: Creates a new SAML RP via samlgw2 API.
 */

import {
  DynamoDBClient,
  GetItemCommand,
  QueryCommand,
  ScanCommand,
} from '@aws-sdk/client-dynamodb';
import { validateTenantAccess, getTenantIdFromRequest, createResponse, createLogger } from 'admin-auth';
import {
  createSamlGw2ClientFromEnv,
  buildSamlgw2ItorgId,
  isEncodableSamlRpName,
} from '../samlgw2-client/index.mjs';

import postResData from './post.mjs';

const logger = createLogger('samlslist');

const dynamodb = new DynamoDBClient({ region: process.env.AWS_REGION });
const tenantTable = process.env.AMFATENANT_TABLE;

/**
 * Look up the samlgw2 IT Org ID for a tenant's org.
 */
async function getSamlgw2ItorgId(tenantOrgId) {
  try {
    const result = await dynamodb.send(new QueryCommand({
      TableName: tenantTable,
      KeyConditionExpression: 'id = :id AND begins_with(sk, :sk_prefix)',
      ExpressionAttributeValues: {
        ':id': { S: `ORG#${tenantOrgId}` },
        ':sk_prefix': { S: 'ORG#' },
      },
      ProjectionExpression: 'samlgw2_itorg_id',
    }));

    const stored = result.Items?.[0]?.samlgw2_itorg_id?.S;
    if (stored) return stored;
  } catch (e) {
    logger.info('Failed to query org samlgw2_itorg_id:', e.message);
  }

  return buildSamlgw2ItorgId(process.env.ACCOUNT_ID, tenantOrgId);
}

/**
 * Get tenant info from DynamoDB.
 */
async function getTenantInfo(tenantId) {
  const result = await dynamodb.send(new QueryCommand({
    TableName: tenantTable,
    KeyConditionExpression: 'id = :id AND begins_with(sk, :sk_prefix)',
    ExpressionAttributeValues: {
      ':id': { S: `TENANT#${tenantId}` },
      ':sk_prefix': { S: 'TENANT#' },
    },
  }));

  if (!result.Items || result.Items.length === 0) return null;

  const item = result.Items[0];
  return {
    orgId: item.org_id?.S,
    userPoolId: item.userpool?.S,
    samlClientId: item.samlClientId?.S,
  };
}

export const handler = async (event) => {
  console.info('EVENT\n' + JSON.stringify(event, null, 2));

  let errMsg = { type: 'exception', message: 'Service Error' };

  try {
    // Multi-tenant: resolve tenant from X-Tenant-Id header
    const tenantId = getTenantIdFromRequest(event);
    if (!tenantId) {
      return createResponse(400, { error: 'tenant_id required in request' });
    }

    const authResult = await validateTenantAccess(event, tenantId);
    if (!authResult.authorized) {
      return createResponse(authResult.statusCode, { error: authResult.error });
    }

    const spInfoTable = `amfa-spinfo-${tenantId}`;
    logger.info(`Tenant ${tenantId}, spInfoTable: ${spInfoTable}`);

    if (event.requestContext.http.method === 'POST' && (!event.queryStringParameters || !event.queryStringParameters.page)) {
      // CREATE new SAML RP
      const body = JSON.parse(event.body);
      logger.info('POST data:', body);
      const postResult = await postResData(body.data, dynamodb, tenantId, tenantTable, spInfoTable);

      logger.info('postResult', postResult);

      return {
        statusCode: postResult.statusCode,
        headers: {
          'Access-Control-Allow-Headers': 'Content-Type,Authorization,X-Api-Key,X-Tenant-Id,Content-Range,X-Requested-With',
          'Access-Control-Allow-Origin': '*',
          'Access-Control-Allow-Methods': 'OPTIONS,GET,POST',
          'Access-Control-Expose-Headers': 'Content-Range',
          'Content-Type': 'application/json',
          'Access-Control-Allow-Credentials': true,
        },
        body: postResult.body,
      };
    } else {
      // LIST all SAML RPs
      const tenantInfo = await getTenantInfo(tenantId);
      let data = [];

      if (tenantInfo?.orgId) {
        const itorgId = await getSamlgw2ItorgId(tenantInfo.orgId);
        const customerName = tenantId.toLowerCase();

        try {
          // Fetch customer data from samlgw2 (includes all relying_parties)
          const samlgw2 = createSamlGw2ClientFromEnv();
          const customerData = await samlgw2.getCustomer(itorgId, customerName);

          const relyingParties = customerData?.doc?.relying_parties || {};

          // Build list from samlgw2 data + DynamoDB SP info
          for (const [rpName, rpConfig] of Object.entries(relyingParties)) {
            // getIdpMetadataUrl throws for names it cannot encode as a path
            // segment; skip those RPs instead of failing the whole list.
            if (!isEncodableSamlRpName(rpName)) {
              logger.warn(`Skipping RP with unencodable name: ${rpName}`);
              continue;
            }
            // Get SP info from DynamoDB (released, logoUrl, serviceUrl overrides)
            let spInfo = null;
            try {
              const spInfoRes = await dynamodb.send(new GetItemCommand({
                TableName: spInfoTable,
                Key: { id: { S: `#SAML#${rpName}` } },
              }));

              if (spInfoRes?.Item?.id) {
                spInfo = {
                  logoUrl: spInfoRes.Item.logoUrl?.S || '',
                  serviceUrl: spInfoRes.Item.serviceUrl?.S || '',
                  released: spInfoRes.Item.released?.BOOL || false,
                  template: spInfoRes.Item.template?.S || 'custom',
                };
              }
            } catch (e) {
              logger.info(`Failed to get spInfo for ${rpName}:`, e.message);
            }

            const idpMetadataUrl = samlgw2.getIdpMetadataUrl(itorgId, customerName, rpName);

            data.push({
              id: rpName,
              rpName,
              name: rpConfig.display_name || rpName,
              metadataUrl: rpConfig.sp?.metadata_url || '',
              serviceUrl: spInfo?.serviceUrl || rpConfig.login_url || '',
              logoUrl: spInfo?.logoUrl || rpConfig.logo_url || '',
              released: spInfo?.released || false,
              template: spInfo?.template || 'custom',
              idpMetadataUrl,
            });
          }
        } catch (gw2Error) {
          logger.error('Failed to fetch samlgw2 customer data:', gw2Error.message);
          // Fall back to DynamoDB-only data if samlgw2 is unreachable
          try {
            const scanResult = await dynamodb.send(new ScanCommand({
              TableName: spInfoTable,
              FilterExpression: 'begins_with(id, :prefix)',
              ExpressionAttributeValues: {
                ':prefix': { S: '#SAML#' },
              },
            }));

            data = (scanResult.Items || []).map(item => ({
              id: item.rpName?.S || item.id.S.replace('#SAML#', ''),
              rpName: item.rpName?.S || item.id.S.replace('#SAML#', ''),
              name: item.name?.S || '',
              metadataUrl: item.metadataUrl?.S || '',
              serviceUrl: item.serviceUrl?.S || '',
              logoUrl: item.logoUrl?.S || '',
              released: item.released?.BOOL || false,
              template: item.template?.S || 'custom',
              idpMetadataUrl: item.idpMetadataUrl?.S || '',
            }));
          } catch (scanError) {
            logger.error('DynamoDB fallback scan also failed:', scanError.message);
          }
        }
      }

      // Sort by name
      data.sort((a, b) => (a.name || '').localeCompare(b.name || ''));

      const page = parseInt(event.queryStringParameters?.page || '1');
      const perPage = parseInt(event.queryStringParameters?.perPage || '25');
      const start = (page - 1) * perPage;
      const end = Math.min(start + perPage, data.length) - 1;

      return {
        statusCode: 200,
        headers: {
          'Access-Control-Allow-Headers': 'Content-Type,Authorization,X-Api-Key,X-Tenant-Id,Content-Range,X-Requested-With',
          'Access-Control-Allow-Origin': '*',
          'Access-Control-Allow-Methods': 'OPTIONS,GET,POST',
          'Access-Control-Expose-Headers': 'Content-Range',
          'Content-Range': `samls ${start}-${end >= 0 ? end : 0}`,
        },
        body: JSON.stringify({
          data: data.slice(start, start + perPage),
          total: data.length,
        }),
      };
    }
  } catch (e) {
    logger.info('Catch an error:', e);
    switch (e.name) {
      case 'ThrottlingException':
        errMsg = { type: 'exception', message: 'Too many requests' };
        break;
      case 'InvalidParameterValue':
      case 'InvalidParameterException':
        errMsg = { type: 'exception', message: 'Invalid parameter' };
        break;
      default:
        errMsg = { type: 'exception', message: 'Service Error' };
        break;
    }
  }

  return {
    statusCode: 500,
    body: JSON.stringify(errMsg),
  };
};
